// ZigBee2MQTT Daten parsen
let data = msg.payload;
let deviceInfo = {};

// Prüfen ob Daten vorhanden sind
if (typeof data === 'object') {
    // Batteriestatus (in % oder Spannung)
    deviceInfo.battery = data.battery || data.battery_percentage || 0;
    deviceInfo.battery_low = data.battery_low || false;

    // Test-Modus (falls vorhanden)
    deviceInfo.test_mode = data.test_mode || false;

    // Rauchmelder Status (Alarm, Normal, etc.)
    deviceInfo.smoke = data.smoke || false;
    deviceInfo.smoke_detected = data.smoke_detected || false;

    // Zusätzliche Status-Felder für HS1SA-E
    deviceInfo.trouble = data.trouble || false;
    deviceInfo.tamper = data.tamper || false;

    // Link Quality
    deviceInfo.linkquality = data.linkquality || 0;

    // Last seen aus ZigBee2MQTT
    deviceInfo.last_seen = data.last_seen || new Date().toISOString();

    // Batterie OK Status berechnen
    deviceInfo.battery_ok = true;
    if (deviceInfo.battery_low === true || 
        (typeof deviceInfo.battery === 'number' && deviceInfo.battery < 20)) {
        deviceInfo.battery_ok = false;
    }

    // Timestamp für die aktuelle Abfrage
    deviceInfo.timestamp = new Date().toISOString();
    deviceInfo.timestamp_formatted = new Date().toLocaleString('de-DE');

    deviceInfo.friendly_name = "KellerWerkstatt";

    msg.payload = deviceInfo;

    return msg;
}

return msg;

// Statusbericht formatieren
const data = msg.payload;
const friendlyName = data.friendly_name || "Rauchmelder Keller Werkstatt";
const timestamp = new Date().toLocaleString('de-DE', {
    weekday: 'long',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
});

// Batteriestatus
let batteryEmoji = "🔋";
let batteryStatus = "";
if (data.battery <= 20) {
    batteryEmoji = "⚠️🔴";
    batteryStatus = "KRITISCH - SOFORT WECHSELN!";
} else if (data.battery <= 50) {
    batteryEmoji = "⚠️🟡";
    batteryStatus = "Bald wechseln";
} else if (data.battery <= 80) {
    batteryEmoji = "🟢";
    batteryStatus = "Gut";
} else {
    batteryEmoji = "💚";
    batteryStatus = "Sehr gut";
}

// Geräte-Status
let deviceStatus = "✅ OK";
if (data.battery_low) deviceStatus = "⚠️ Batterie schwach";
if (data.trouble) deviceStatus = "🔴 Störung";
if (data.tamper) deviceStatus = "🔧 Manipulation";
if (data.smoke) deviceStatus = "🚨 RAUCHALARM!";

// Linkqualität (LQI: 0-255)
let linkQualityText = "🔴 Schlecht";
if (data.linkquality >= 200) linkQualityText = "🟢 Sehr gut";
else if (data.linkquality >= 150) linkQualityText = "🟢 Gut";
else if (data.linkquality >= 100) linkQualityText = "🟡 Mittel";
else if (data.linkquality >= 50) linkQualityText = "🟠 Schwach";

// Last seen formatieren
let lastSeenStr = "Unbekannt";
if (data.last_seen) {
    try {
        lastSeenStr = new Date(data.last_seen).toLocaleString('de-DE');
    } catch (e) {
        lastSeenStr = data.last_seen;
    }
}

// Statusbericht
const reportTitle = `Statusbericht - Rauchmelder`; // Ohne Emoji für Header
const reportMessage = 
    `📋 ${reportTitle}\n` +
    `Gerät: ${friendlyName}\n` +
    `${batteryEmoji} Batterie: ${data.battery}% - ${batteryStatus}\n` +
    `📶 Signal: ${linkQualityText} (${data.linkquality} LQI)\n` +
    `🔄 Gerätestatus: ${deviceStatus}\n` +
    `🕒 Letzter Kontakt: ${lastSeenStr}\n` +
    `📊 Bericht erstellt: ${timestamp}\n\n` +
    `Letzte Werte:\n` +
    `• Rauch gemeldet: ${data.smoke ? 'Ja 🚨' : 'Nein ✅'}\n` +
    `• Batterie schwach: ${data.battery_low ? 'Ja ⚠️' : 'Nein ✅'}\n` +
    `• Manipulation: ${data.tamper ? 'Ja 🔧' : 'Nein ✅'}\n` +
    `• Störung: ${data.trouble ? 'Ja 🔴' : 'Nein ✅'}\n` +
    `• Test-Modus: ${data.test_mode ? 'Ja 🔧' : 'Nein ✅'}\n\n`;

// Für Pushover
msg.pushover = {
    // url: "https://ntfy.sh/secret-ntfy-theme-Rauchmelder",
    // method: "POST",
    headers: {
        "Title": reportTitle.replace(/[^a-zA-Z0-9\s-]/g, ''), // Entfernt alle Sonderzeichen
        "Tags": data.battery <= 20 ? "warning,rotating_light,battery" : "battery,rotating_light",
        "Priority": data.battery <= 20 ? "high" : "default"
    },
    payload: reportMessage
};

// Für ntfy - Header müssen ASCII-konform sein (keine Umlaute oder Emojis)
msg.ntfy = {
    url: "https://ntfy.sh/secret-ntfy-theme-Rauchmelder",
    method: "POST",
    headers: {
        "Title": reportTitle.replace(/[^a-zA-Z0-9\s-]/g, ''), // Entfernt alle Sonderzeichen
        "Tags": data.battery <= 20 ? "warning,rotating_light,battery" : "battery,rotating_light",
        "Priority": data.battery <= 20 ? "high" : "default"
    },
    payload: reportMessage
};

// Kennzeichnung für Debug
msg.is_battery_report = true;

return msg;

// ntfy Request vorbereiten
const ntfyConfig = msg.ntfy;

// HTTP Request für ntfy erstellen
msg.url = ntfyConfig.url;
msg.method = ntfyConfig.method;
msg.headers = ntfyConfig.headers;
msg.payload = ntfyConfig.payload;

// Debug-Ausgabe (optional, kann später entfernt werden)
node.warn("ntfy Header: " + JSON.stringify(msg.headers));

return msg;

// Pushover Request vorbereiten
const pushoverConfig = msg.pushover;

// HTTP Request für Pushover erstellen
msg.headers = pushoverConfig.headers;
msg.payload = pushoverConfig.payload;

return msg;

// ZigBee2MQTT Daten parsen
let data = msg.payload;
let deviceInfo = {};
let alarmStatus = false;

// Prüfen ob Daten vorhanden sind
if (typeof data === 'object') {
    // Batteriestatus (in % oder Spannung)
    deviceInfo.battery = data.battery || data.battery_percentage || 0;
    deviceInfo.battery_low = data.battery_low || false;

    // Test-Modus (falls vorhanden)
    deviceInfo.test_mode = data.test || false;  // Wichtig: heißt 'test' im HS1SA-E

    // Rauchmelder Status (Alarm!)
    deviceInfo.smoke = data.smoke || false;
    alarmStatus = deviceInfo.smoke;  // Für Alarmerkennung

    // Link Quality
    deviceInfo.linkquality = data.linkquality || 0;

    // Last seen aus ZigBee2MQTT
    deviceInfo.last_seen = data.last_seen || new Date().toISOString();

    // Batterie OK Status berechnen
    deviceInfo.battery_ok = true;
    if (deviceInfo.battery_low === true || 
        (typeof deviceInfo.battery === 'number' && deviceInfo.battery < 20)) {
        deviceInfo.battery_ok = false;
    }

    // Timestamp für die aktuelle Abfrage
    deviceInfo.timestamp = new Date().toISOString();
    deviceInfo.timestamp_formatted = new Date().toLocaleString('de-DE');
    deviceInfo.friendly_name = "Keller Werkstatt";

    // Alarm-Status für nachfolgende Nodes
    msg.payload = deviceInfo;
    msg.alarm_active = alarmStatus;  // Explizites Flag für Alarm
    msg.alarm_triggered = alarmStatus; // Alternative Bezeichnung

    return msg;
}

return msg;

// Blink-Modus für die Kerzenbirne
// Sekundentakt: 1s an, 1s aus

// Aktuellen Zustand der Birne abfragen und speichern
// Dazu müssten Sie den aktuellen Status kennen - hier als Platzhalter
flow.set("light_previous_state", {
    state: "ON",  // Hier müsste der echte Status ermittelt werden
    brightness: 254
});

// Blinken aktivieren
flow.set("blink_active", true);
flow.set("blink_counter", 0);
flow.set("blink_state", "OFF");  // Startet mit OFF, dann wechselt zu ON

// Ersten Befehl senden (Licht an in Rot)
msg.topic = "zigbee2mqtt/KerzenbirneBuero/set";
msg.payload = {
    "state": "ON",
    "brightness": 254,
    "color": { "hex": "#FF0000" }
};

node.warn("Alarm-Blinken gestartet");

return msg;

// Diese Funktion erzeugt den Sekundentakt
// Sie wird von einem Inject-Node im Sekundentakt aufgerufen

// Aktuellen Zustand aus Flow-Kontext holen
let currentState = flow.get("blink_state") || "OFF";
let counter = flow.get("blink_counter") || 0;
let blinkActive = flow.get("blink_active") || false;

// Prüfen ob Blinken aktiv ist (vom Trigger gesetzt)
if (!blinkActive) {
    // Wenn nicht aktiv, nichts tun
    return null;
}

// Zustand umschalten
let newState = (currentState === "ON") ? "OFF" : "ON";
flow.set("blink_state", newState);

// Zähler erhöhen
counter++;
flow.set("blink_counter", counter);

// Nach 30 Sekunden automatisch beenden (30 Toggles = 30 Sekunden bei 1s Intervall)
if (counter >= 30) {
    // Blinken beenden
    flow.set("blink_counter", 0);
    flow.set("blink_state", "OFF");
    flow.set("blink_active", false);

    // Vorherigen Zustand wiederherstellen
    let previousState = flow.get("light_previous_state") || { state: "OFF" };

    msg.topic = "zigbee2mqtt/KerzenbirneBuero/set";
    msg.payload = {
        "state": previousState.state || "OFF"
    };

    node.warn("Alarm-Blinken nach 30s beendet");
    return msg;
}

// Befehl für die Kerzenbirne
msg.topic = "zigbee2mqtt/KerzenbirneBuero/set";
if (newState === "ON") {
    msg.payload = {
        "state": "ON",
        "brightness": 254,
        "color": { "hex": "#FF0000" }  // Rot
    };
} else {
    msg.payload = {
        "state": "OFF"
    };
}

return msg;

// Blinken stoppen
flow.set("blink_active", false);
flow.set("blink_counter", 0);
flow.set("blink_state", "OFF");

// Vorherigen Zustand wiederherstellen
let previousState = flow.get("light_previous_state") || { state: "OFF" };

msg.topic = "zigbee2mqtt/KerzenbirneBuero/set";
msg.payload = {
    "state": previousState.state || "OFF"
};

node.warn("Alarm-Blinken gestoppt");

return msg;

// Alarm-Benachrichtigung für Pushover
const data = msg.payload;
const timestamp = new Date().toLocaleString('de-DE', {
    weekday: 'long',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
});

// Gerätename ermitteln (mit Fallback)
const deviceName = data.friendly_name || 'Rauchmelder Werkstatt';

// Alarm-Nachricht formatieren
let alarmMessage =
    `🚨 RAUCHALARM! 🚨

Gerät: ${deviceName}
Zeit: ${timestamp}

📍 Bereich: ${deviceName}
⚠️ Es wurde RAUCH detektiert!

Bitte überprüfen Sie den Bereich SOFORT!`;

// Pushover-spezifische Felder
msg.title = `🚨 RAUCHALARM - ${deviceName}`;
msg.payload = alarmMessage;
msg.priority = 1;              // High Priority
msg.sound = "persistent";       // Alarmton
msg.timestamp = Math.floor(Date.now() / 1000);

return msg;
